import{_ as e,o as d,c as a,a0 as r}from"./chunks/framework.CzVS_xMp.js";const y=JSON.parse('{"title":"InfiniBand 패킷 형식 참조 문서","description":"","frontmatter":{},"headers":[],"relativePath":"network/ib-packet-analysis/packet-format-reference_KO.md","filePath":"network/ib-packet-analysis/packet-format-reference_KO.md","lastUpdated":1788432796000}'),i={name:"network/ib-packet-analysis/packet-format-reference_KO.md"};function l(o,t,n,s,h,c){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="infiniband-패킷-형식-참조-문서" tabindex="-1">InfiniBand 패킷 형식 참조 문서 <a class="header-anchor" href="#infiniband-패킷-형식-참조-문서" aria-label="Permalink to &quot;InfiniBand 패킷 형식 참조 문서&quot;">​</a></h1><p><a href="./packet-format-reference">English</a> | <strong>한국어</strong></p><p>이 문서는 InfiniBand 패킷 헤더를 비트 단위로 정리한 참조 문서이며, <a href="./README_KO">메인 분석 보고서</a>를 보완하도록 작성되었습니다. 보고서가 <code>ib-packets</code> 데이터셋에서 무엇이 관측되었는지에 초점을 둔다면, 이 문서는 IB 패킷 헤더가 실제 전송 형식에서 어떻게 배치되는지에 초점을 둡니다. 구체적인 예시가 있는 곳에는 보고서의 프레임 수준 증거로 이어지는 앵커 링크를 제공합니다.</p><p>이 문서를 사용하는 경우:</p><ul><li>헥스 덤프를 읽고 필드 경계를 식별할 때</li><li>주어진 BTH opcode 다음에 어떤 확장 헤더가 와야 하는지 검증할 때</li><li>AETH syndrome 값을 디코드할 때</li><li>모든 전송 서비스에 걸쳐 BTH opcode를 조회할 때</li></ul><p>원천 자료: IBA Architecture Specification Volume 1 (Release 1.5), Wireshark InfiniBand dissector 필드 목록, <a href="https://cloud.tencent.com/developer/article/2513460" target="_blank" rel="noreferrer">Tencent Cloud 전송 계층 글</a>.</p><h2 id="목차" tabindex="-1">목차 <a class="header-anchor" href="#목차" aria-label="Permalink to &quot;목차&quot;">​</a></h2><ul><li><a href="#헤더-시퀀스-개요">헤더 시퀀스 개요</a></li><li><a href="#local-route-header-lrh--8-bytes">Local Route Header (LRH) — 8 bytes</a></li><li><a href="#global-route-header-grh--40-bytes">Global Route Header (GRH) — 40 bytes</a></li><li><a href="#base-transport-header-bth--12-bytes">Base Transport Header (BTH) — 12 bytes</a></li><li><a href="#extended-transport-headers">Extended Transport Headers</a><ul><li><a href="#deth--8-bytes-datagram-eth">DETH — 8 bytes</a></li><li><a href="#reth--16-bytes-rdma-eth">RETH — 16 bytes</a></li><li><a href="#aeth--4-bytes-ack-eth">AETH — 4 bytes</a></li><li><a href="#atomiceth--28-bytes">AtomicETH — 28 bytes</a></li><li><a href="#atomicacketh--8-bytes">AtomicAckETH — 8 bytes</a></li><li><a href="#immdt--4-bytes-immediate-data">ImmDt — 4 bytes</a></li><li><a href="#ieth--4-bytes-invalidate-eth">IETH — 4 bytes</a></li><li><a href="#rdeth--4-bytes-reliable-datagram-eth">RDETH — 4 bytes</a></li><li><a href="#xrceth--4-bytes-extended-reliable-connection-eth">XRCETH — 4 bytes</a></li></ul></li><li><a href="#mad-common-header--24-bytes">MAD Common Header — 24 bytes</a></li><li><a href="#smp-directed-route-extension">SMP Directed Route Extension</a></li><li><a href="#ipoib-encapsulation--4-bytes-rfc-4391">IPoIB Encapsulation — 4 bytes (RFC 4391)</a></li><li><a href="#crc-커버리지">CRC 커버리지</a></li><li><a href="#bth-opcode-마스터-표">BTH Opcode 마스터 표</a></li><li><a href="#operation--extended-header-매핑">Operation → Extended Header 매핑</a></li><li><a href="#참고">참고</a></li></ul><h2 id="헤더-시퀀스-개요" tabindex="-1">헤더 시퀀스 개요 <a class="header-anchor" href="#헤더-시퀀스-개요" aria-label="Permalink to &quot;헤더 시퀀스 개요&quot;">​</a></h2><p>IB 패킷의 실제 전송 형식은 헤더, 페이로드, CRC가 엄격한 순서로 이어진 구조입니다. 어떤 확장 헤더가 어떤 순서로 나타나는지는 <code>LRH.LNH</code>(GRH 존재 여부)와 BTH opcode(어떤 확장 헤더가 따르는지)로 완전히 결정됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----+-------+-----+-----------------------+----------+------+------+</span></span>
<span class="line"><span>| LRH |  GRH? | BTH | Extended Header(s)    | Payload  | ICRC | VCRC |</span></span>
<span class="line"><span>+-----+-------+-----+-----------------------+----------+------+------+</span></span>
<span class="line"><span>   8     40    12      0..28+ bytes            variable    4      2</span></span></code></pre></div><ul><li><code>GRH</code>는 <code>LRH.LNH = 0x3</code>일 때만 존재합니다.</li><li>확장 헤더의 종류와 순서는 <a href="#operation--extended-header-매핑">Operation → Extended Header 매핑</a>을 따릅니다.</li><li><code>ICRC</code>와 <code>VCRC</code>는 실제 전송 형식에서 항상 패킷의 끝에 위치합니다.</li></ul><h2 id="local-route-header-lrh-—-8-bytes" tabindex="-1">Local Route Header (LRH) — 8 bytes <a class="header-anchor" href="#local-route-header-lrh-—-8-bytes" aria-label="Permalink to &quot;Local Route Header (LRH) — 8 bytes&quot;">​</a></h2><p>LRH는 모든 패킷의 첫 IB 헤더이며 fabric 로컬 라우팅에 사용됩니다.</p><p>비트 레이아웃 (big-endian):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte</th><th>비트 패턴</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td><code>VVVV LLLL</code></td><td>VL[3:0] / LVer[3:0]</td><td style="text-align:right;">4 + 4</td></tr><tr><td style="text-align:right;">1</td><td><code>SSSS RR NN</code></td><td>SL[3:0] / Reserved / LNH[1:0]</td><td style="text-align:right;">4 + 2 + 2</td></tr><tr><td style="text-align:right;">2..3</td><td><code>DDDDDDDD DDDDDDDD</code></td><td>DLID</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">4</td><td><code>RRRRR PPP</code></td><td>Reserved / PktLen[10:8]</td><td style="text-align:right;">5 + 3</td></tr><tr><td style="text-align:right;">5</td><td><code>PPPPPPPP</code></td><td>PktLen[7:0]</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">6..7</td><td><code>SSSSSSSS SSSSSSSS</code></td><td>SLID</td><td style="text-align:right;">16</td></tr></tbody></table><p>필드 의미:</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td>VL</td><td>Virtual Lane (0–15). VL15는 관리 트래픽용으로 예약</td></tr><tr><td>LVer</td><td>Link version, 현재는 항상 0</td></tr><tr><td>SL</td><td>Service Level (0–15), QoS 클래스에 매핑</td></tr><tr><td>LNH</td><td>Link Next Header — LRH 다음에 오는 것을 선택</td></tr><tr><td>DLID / SLID</td><td>Destination / Source Local ID (SM이 할당)</td></tr><tr><td>PktLen</td><td>4바이트 워드 단위의 패킷 길이, LRH와 VCRC 제외</td></tr></tbody></table><p>LNH 인코딩:</p><table tabindex="0"><thead><tr><th style="text-align:right;">값</th><th>의미</th><th>LRH 다음에 오는 것</th></tr></thead><tbody><tr><td style="text-align:right;"><code>0x0</code></td><td>Raw IPv6 (legacy)</td><td>IPv6 헤더 직접</td></tr><tr><td style="text-align:right;"><code>0x1</code></td><td>Raw IPv4 (legacy)</td><td>IPv4 헤더 직접</td></tr><tr><td style="text-align:right;"><code>0x2</code></td><td>IBA Local</td><td>BTH (GRH 없음)</td></tr><tr><td style="text-align:right;"><code>0x3</code></td><td>IBA Global</td><td>GRH + BTH</td></tr></tbody></table><p>구체적 예시: 이 데이터셋의 모든 패킷은 <code>LNH = 0x2</code>를 가지므로 GRH가 디코드되지 않습니다. <code>infiniband.pcap</code> frame 10의 단계별 예제는 메인 보고서의 <a href="./README_KO#erf-캡처-해부">ERF 캡처 해부</a> 섹션을 참고하세요.</p><h2 id="global-route-header-grh-—-40-bytes" tabindex="-1">Global Route Header (GRH) — 40 bytes <a class="header-anchor" href="#global-route-header-grh-—-40-bytes" aria-label="Permalink to &quot;Global Route Header (GRH) — 40 bytes&quot;">​</a></h2><p>GRH는 <code>LRH.LNH = 0x3</code>일 때만 나타나며 IB 서브넷 사이의 라우팅을 신호합니다. 포맷은 IPv6를 본떴습니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0 (high 4)</td><td>IPVer</td><td style="text-align:right;">4</td></tr><tr><td style="text-align:right;">0 (low 4) + 1 (high 4)</td><td>TClass</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">1 (low 4) + 2..3</td><td>FlowLabel</td><td style="text-align:right;">20</td></tr><tr><td style="text-align:right;">4..5</td><td>PayLen</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">6</td><td>NxtHdr</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">7</td><td>HopLmt</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">8..23</td><td>SGID</td><td style="text-align:right;">128</td></tr><tr><td style="text-align:right;">24..39</td><td>DGID</td><td style="text-align:right;">128</td></tr></tbody></table><p>비고:</p><ul><li><code>IPVer</code>는 항상 6입니다.</li><li><code>NxtHdr = 0x1B</code>(27 십진수)는 IBA next header(BTH)를 신호합니다.</li><li><code>PayLen</code>은 GRH 다음부터 ICRC 시작 지점까지의 바이트를 셉니다.</li><li>SGID/DGID는 SM이 할당한 128비트 GID입니다.</li></ul><p>이 데이터셋은 GRH를 가진 패킷을 포함하지 않으므로, 이 섹션은 향후 서브넷 간 캡처를 해석하기 위한 순수 참조 자료입니다.</p><h2 id="base-transport-header-bth-—-12-bytes" tabindex="-1">Base Transport Header (BTH) — 12 bytes <a class="header-anchor" href="#base-transport-header-bth-—-12-bytes" aria-label="Permalink to &quot;Base Transport Header (BTH) — 12 bytes&quot;">​</a></h2><p>BTH는 전송 동작, 목적지 QP, packet sequence number를 선택합니다. 모든 IBA 패킷에 나타납니다 (즉 <code>LNH ∈ {0x2, 0x3}</code>).</p><p>비트 레이아웃:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OpCode</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">1 (bit 7)</td><td>SE (Solicited Event)</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">1 (bit 6)</td><td>M (Migration request)</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">1 (bits 5..4)</td><td>PadCnt</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">1 (bits 3..0)</td><td>TVer</td><td style="text-align:right;">4</td></tr><tr><td style="text-align:right;">2..3</td><td>P_Key</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">4 (bit 7)</td><td>F (FECN)</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">4 (bit 6)</td><td>B (BECN)</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">4 (bits 5..0)</td><td>Reserved</td><td style="text-align:right;">6</td></tr><tr><td style="text-align:right;">5..7</td><td>DestQP</td><td style="text-align:right;">24</td></tr><tr><td style="text-align:right;">8 (bit 7)</td><td>A (AckReq)</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">8 (bits 6..0)</td><td>Reserved</td><td style="text-align:right;">7</td></tr><tr><td style="text-align:right;">9..11</td><td>PSN</td><td style="text-align:right;">24</td></tr></tbody></table><p>필드 의미:</p><table tabindex="0"><thead><tr><th>필드</th><th>비고</th></tr></thead><tbody><tr><td>OpCode</td><td>상위 3비트 = 전송 서비스, 하위 5비트 = 동작. <a href="#bth-opcode-마스터-표">BTH Opcode 마스터 표</a> 참고</td></tr><tr><td>SE</td><td>Solicited Event — 응답자의 CQ 이벤트를 트리거해야 하는 SEND 또는 RDMA WRITE 메시지의 마지막 패킷에 설정</td></tr><tr><td>M</td><td>자동 path migration 중 request / accept 신호로 사용</td></tr><tr><td>PadCnt</td><td>페이로드 끝에 추가되는 0–3 바이트로 4바이트 경계에 정렬</td></tr><tr><td>TVer</td><td>Transport header version, 현재는 항상 0</td></tr><tr><td>P_Key</td><td>파티션 키; 상위 비트 = full vs limited 멤버십, 하위 15비트 = 파티션 ID</td></tr><tr><td>FECN / BECN</td><td>Forward / Backward Explicit Congestion Notification</td></tr><tr><td>DestQP</td><td>24비트 destination Queue Pair 번호</td></tr><tr><td>AckReq</td><td>RC 트래픽에서 설정 시 응답자가 ACK를 생성해야 함</td></tr><tr><td>PSN</td><td>24비트 Packet Sequence Number; 2²⁴로 wrap</td></tr></tbody></table><p>알아둘 가치가 있는 PSN 동작:</p><ul><li>expected PSN은 QP마다 추적됩니다. PSN이 expected 값과 같은 패킷은 윈도우를 전진시킵니다.</li><li><em>duplicate range</em> 안의 PSN(expected보다 오래되었지만 2²³ 이내)은 재전송으로 다뤄지며 페이로드를 다시 전달하지 않고 ACK됩니다.</li><li>duplicate range를 벗어나면서 expected보다 이른 PSN은 sequence error이며 코드 0의 NAK를 트리거합니다.</li></ul><p>구체적 예시: <code>infiniband.pcap</code> frame 10 BTH:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opcode  = 4   (RC SEND Only)</span></span>
<span class="line"><span>SE = 0, M = 1, PadCnt = 0, TVer = 0</span></span>
<span class="line"><span>P_Key   = 0xffff   (full membership, 기본 파티션)</span></span>
<span class="line"><span>FECN = 0, BECN = 0</span></span>
<span class="line"><span>DestQP  = &lt;masked&gt;</span></span>
<span class="line"><span>AckReq  = 1</span></span>
<span class="line"><span>PSN     = 13896277</span></span></code></pre></div><h2 id="extended-transport-headers" tabindex="-1">Extended Transport Headers <a class="header-anchor" href="#extended-transport-headers" aria-label="Permalink to &quot;Extended Transport Headers&quot;">​</a></h2><p>BTH 다음에 어떤 확장 헤더가 따르는지는 opcode가 완전히 결정합니다. IBA 사양은 이를 opcode별 표로 인코딩합니다. 동작별 요약은 <a href="#operation--extended-header-매핑">Operation → Extended Header 매핑</a>에 있습니다.</p><h3 id="deth-—-8-bytes-datagram-eth" tabindex="-1">DETH — 8 bytes (Datagram ETH) <a class="header-anchor" href="#deth-—-8-bytes-datagram-eth" aria-label="Permalink to &quot;DETH — 8 bytes (Datagram ETH)&quot;">​</a></h3><p>UD와 RD 동작에 필요합니다. QP0/QP1을 통한 모든 MAD 트래픽도 사용합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..3</td><td>Q_Key</td><td style="text-align:right;">32</td></tr><tr><td style="text-align:right;">4</td><td>Reserved</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">5..7</td><td>SrcQP</td><td style="text-align:right;">24</td></tr></tbody></table><p>Q_Key 관례:</p><ul><li>QP0 (SMP): <code>Q_Key = 0</code></li><li>QP1 (GMP): <code>Q_Key = 0x80010000</code></li><li>그 외 UD QP: 애플리케이션 정의; 상위 비트 설정 = privileged</li></ul><p>구체적 예시: <code>infiniband.pcap</code> frame 1 SMP 트래픽은 <code>DestQP = 0x000000</code>, <code>SrcQP = 0x00000000</code>, <code>Q_Key = 0x00000000</code>을 사용합니다.</p><h3 id="reth-—-16-bytes-rdma-eth" tabindex="-1">RETH — 16 bytes (RDMA ETH) <a class="header-anchor" href="#reth-—-16-bytes-rdma-eth" aria-label="Permalink to &quot;RETH — 16 bytes (RDMA ETH)&quot;">​</a></h3><p><code>RDMA READ Request</code>, <code>RDMA WRITE First</code>, <code>RDMA WRITE Only</code>, with-Immediate 변종에 존재합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..7</td><td>VA (Virtual Address)</td><td style="text-align:right;">64</td></tr><tr><td style="text-align:right;">8..11</td><td>R_Key</td><td style="text-align:right;">32</td></tr><tr><td style="text-align:right;">12..15</td><td>DMALen</td><td style="text-align:right;">32</td></tr></tbody></table><p>응답자는 <code>R_Key</code>에 등록된 MR과 비교해 요청을 검증해야 합니다. VA는 MR 주소 범위 안에 있어야 하고, <code>[VA, VA + DMALen)</code>은 그 경계를 벗어나면 안 되며, MR의 접근 권한에는 필요한 READ 또는 WRITE 권한이 포함되어야 합니다.</p><p>이 데이터셋에는 RETH를 가진 패킷이 없습니다.</p><h3 id="aeth-—-4-bytes-ack-eth" tabindex="-1">AETH — 4 bytes (ACK ETH) <a class="header-anchor" href="#aeth-—-4-bytes-ack-eth" aria-label="Permalink to &quot;AETH — 4 bytes (ACK ETH)&quot;">​</a></h3><p>RC와 RD ACK 패킷, 그리고 RDMA READ의 first/last/only 응답 패킷에 존재합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Syndrome</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">1..3</td><td>MSN (Message Sequence Number)</td><td style="text-align:right;">24</td></tr></tbody></table><p>Syndrome 인코딩 (8비트):</p><table tabindex="0"><thead><tr><th style="text-align:right;">비트</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">7</td><td>Reserved</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">6..5</td><td>OpCode</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">4..0</td><td>Value</td><td style="text-align:right;">5</td></tr></tbody></table><p>OpCode 값:</p><table tabindex="0"><thead><tr><th>OpCode</th><th>의미</th><th>Value 필드 해석</th></tr></thead><tbody><tr><td><code>00</code></td><td>ACK</td><td>Credit Count (0–30); <code>31</code> = credit 정보 미제공</td></tr><tr><td><code>01</code></td><td>RNR NAK</td><td>RNR Timer (고정 표에서 retry delay 선택; IBA §9.7.5.2.8 참고)</td></tr><tr><td><code>10</code></td><td>Reserved</td><td>—</td></tr><tr><td><code>11</code></td><td>NAK</td><td>NAK code: <code>0</code>=PSN seq error, <code>1</code>=invalid request, <code>2</code>=remote access error, <code>3</code>=remote operation error, <code>4</code>=invalid RD request</td></tr></tbody></table><p>구체적 예시: <code>infiniband.pcap</code> frame 11은 <code>Syndrome = 31</code> 십진수 = <code>0x1F</code> = <code>0 00 11111</code>입니다. 이는 <code>OpCode = 00 (ACK), Value = 11111 (credit 정보 없음)</code>으로 디코드됩니다. 즉 흐름 제어 힌트가 없는 정상 acknowledgement입니다. 문맥은 <a href="./README_KO#infinibandpcap">메인 보고서의 frame-11 매핑</a>을 참고하세요.</p><h3 id="atomiceth-—-28-bytes" tabindex="-1">AtomicETH — 28 bytes <a class="header-anchor" href="#atomiceth-—-28-bytes" aria-label="Permalink to &quot;AtomicETH — 28 bytes&quot;">​</a></h3><p>RC <code>CmpSwap</code>과 <code>FetchAdd</code> 요청 패킷에 존재합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..7</td><td>VA</td><td style="text-align:right;">64</td></tr><tr><td style="text-align:right;">8..11</td><td>R_Key</td><td style="text-align:right;">32</td></tr><tr><td style="text-align:right;">12..19</td><td>Swap Data (CmpSwap) / Add Data (FetchAdd)</td><td style="text-align:right;">64</td></tr><tr><td style="text-align:right;">20..27</td><td>Compare Data (CmpSwap) / Reserved (FetchAdd)</td><td style="text-align:right;">64</td></tr></tbody></table><p>Atomic 동작은 at-most-once 보장입니다 — 재시도된 요청은 QP별 outstanding-atomic 큐와 매칭되어 read-modify-write를 다시 실행하지 않고 재전송됩니다.</p><p>이 데이터셋에는 atomic 동작이 없습니다.</p><h3 id="atomicacketh-—-8-bytes" tabindex="-1">AtomicAckETH — 8 bytes <a class="header-anchor" href="#atomicacketh-—-8-bytes" aria-label="Permalink to &quot;AtomicAckETH — 8 bytes&quot;">​</a></h3><p>원래 값, 즉 atomic 적용 전의 값을 요청자에게 다시 운반합니다. <code>ATOMIC Acknowledge</code> 패킷에서 AETH 다음에 위치합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..7</td><td>Original Remote Data</td><td style="text-align:right;">64</td></tr></tbody></table><h3 id="immdt-—-4-bytes-immediate-data" tabindex="-1">ImmDt — 4 bytes (Immediate Data) <a class="header-anchor" href="#immdt-—-4-bytes-immediate-data" aria-label="Permalink to &quot;ImmDt — 4 bytes (Immediate Data)&quot;">​</a></h3><p>수신자의 CQE에 전달되는 32비트 불투명 데이터를 운반합니다. 이름이 &quot;with Immediate&quot;로 끝나는 opcode에 존재합니다. 항상 extended header 중 마지막에 위치합니다 (<code>RDMA WRITE Only/Last with Immediate</code>인 경우 RETH 다음).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..3</td><td>Immediate Data</td><td style="text-align:right;">32</td></tr></tbody></table><h3 id="ieth-—-4-bytes-invalidate-eth" tabindex="-1">IETH — 4 bytes (Invalidate ETH) <a class="header-anchor" href="#ieth-—-4-bytes-invalidate-eth" aria-label="Permalink to &quot;IETH — 4 bytes (Invalidate ETH)&quot;">​</a></h3><p>응답자에서 무효화할 R_Key를 운반합니다. <code>SEND Last with Invalidate</code>와 <code>SEND Only with Invalidate</code>에 존재합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..3</td><td>R_Key</td><td style="text-align:right;">32</td></tr></tbody></table><h3 id="rdeth-—-4-bytes-reliable-datagram-eth" tabindex="-1">RDETH — 4 bytes (Reliable Datagram ETH) <a class="header-anchor" href="#rdeth-—-4-bytes-reliable-datagram-eth" aria-label="Permalink to &quot;RDETH — 4 bytes (Reliable Datagram ETH)&quot;">​</a></h3><p>Reliable Datagram (RD) 전송에서 BTH와 DETH/RETH/etc 사이에 사용됩니다. EE (End-to-End) 컨텍스트 번호를 운반합니다. 실제로는 드뭅니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Reserved</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">1..3</td><td>EE Context</td><td style="text-align:right;">24</td></tr></tbody></table><h3 id="xrceth-—-4-bytes-extended-reliable-connection-eth" tabindex="-1">XRCETH — 4 bytes (Extended Reliable Connection ETH) <a class="header-anchor" href="#xrceth-—-4-bytes-extended-reliable-connection-eth" aria-label="Permalink to &quot;XRCETH — 4 bytes (Extended Reliable Connection ETH)&quot;">​</a></h3><p>XRC 전송에서 수신자 측 SRQ를 식별하는 데 사용됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..3</td><td>XRC SRQ</td><td style="text-align:right;">32</td></tr></tbody></table><h2 id="mad-common-header-—-24-bytes" tabindex="-1">MAD Common Header — 24 bytes <a class="header-anchor" href="#mad-common-header-—-24-bytes" aria-label="Permalink to &quot;MAD Common Header — 24 bytes&quot;">​</a></h2><p>모든 MAD 메시지는 관리 클래스에 관계없이 이 24바이트 공통 헤더로 시작합니다. MAD 페이로드가 그 다음에 옵니다 — SMP의 경우 전체 MAD 길이는 256바이트로 고정됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>BaseVersion</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">1</td><td>MgmtClass</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">2</td><td>ClassVersion</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">3</td><td>Method</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">4..5</td><td>Status</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">6..7</td><td>ClassSpecific</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">8..15</td><td>TID (Transaction ID)</td><td style="text-align:right;">64</td></tr><tr><td style="text-align:right;">16..17</td><td>AttributeID</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">18..19</td><td>Reserved</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">20..23</td><td>AttributeModifier</td><td style="text-align:right;">32</td></tr><tr><td style="text-align:right;">24..255</td><td>MAD data payload</td><td style="text-align:right;">232 bytes (SMP)</td></tr></tbody></table><p>이 데이터셋에서 보이는 흔한 MgmtClass 값:</p><table tabindex="0"><thead><tr><th style="text-align:right;">값</th><th>클래스</th><th>사용처</th></tr></thead><tbody><tr><td style="text-align:right;"><code>0x01</code></td><td>SMP (LID-routed)</td><td>LID 기반 Subnet Management</td></tr><tr><td style="text-align:right;"><code>0x03</code></td><td>SubnAdm (SA)</td><td>Path 레코드, MC 멤버 레코드</td></tr><tr><td style="text-align:right;"><code>0x04</code></td><td>Performance Management</td><td><code>PortCounters</code>, <code>PortCountersExtended</code>, <code>ClassPortInfo</code></td></tr><tr><td style="text-align:right;"><code>0x32</code></td><td>Vendor-specific OUI</td><td><code>ibping</code></td></tr><tr><td style="text-align:right;"><code>0x81</code></td><td>SMP (Directed Route)</td><td>초기 fabric 디스커버리 (<code>ib_initial_sniffer.pcap</code>)</td></tr></tbody></table><p>흔한 Method 값:</p><table tabindex="0"><thead><tr><th style="text-align:right;">값</th><th>Method</th><th>비고</th></tr></thead><tbody><tr><td style="text-align:right;"><code>0x01</code></td><td>Get</td><td>속성 읽기</td></tr><tr><td style="text-align:right;"><code>0x02</code></td><td>Set</td><td>속성 쓰기</td></tr><tr><td style="text-align:right;"><code>0x03</code></td><td>Send</td><td>Unsolicited</td></tr><tr><td style="text-align:right;"><code>0x05</code></td><td>Trap</td><td>비동기 통지</td></tr><tr><td style="text-align:right;"><code>0x06</code></td><td>Report</td><td>SA report</td></tr><tr><td style="text-align:right;"><code>0x07</code></td><td>TrapRepress</td><td>반복 trap 억제</td></tr><tr><td style="text-align:right;"><code>0x12</code></td><td>GetTable</td><td>SA 테이블 질의</td></tr><tr><td style="text-align:right;"><code>0x13</code></td><td>GetTraceTable</td><td>SA trace</td></tr><tr><td style="text-align:right;"><code>0x15</code></td><td>GetMulti</td><td>SA multipart</td></tr><tr><td style="text-align:right;"><code>0x81</code></td><td>GetResp</td><td>Get에 대한 응답</td></tr><tr><td style="text-align:right;"><code>0x86</code></td><td>ReportResp</td><td>Report에 대한 응답</td></tr></tbody></table><p>구체적 예시: <code>infiniband.pcap</code> frame 1 = <code>MgmtClass=0x81 (Directed-route SMP), Method=0x01 (Get), AttributeID=0x0020 (SMInfo)</code>. 이는 <code>SubnGet(SMInfo)</code> 패킷입니다.</p><h2 id="smp-directed-route-extension" tabindex="-1">SMP Directed Route Extension <a class="header-anchor" href="#smp-directed-route-extension" aria-label="Permalink to &quot;SMP Directed Route Extension&quot;">​</a></h2><p><code>MgmtClass = 0x81</code>일 때, MAD 공통 헤더 다음에 directed-route 경로를 운반하는 추가 필드가 따릅니다. Wireshark dissector가 노출하고 이 데이터셋에서 보이는 필드들:</p><table tabindex="0"><thead><tr><th>필드</th><th style="text-align:right;">폭</th><th>의미</th></tr></thead><tbody><tr><td>D (Direction Bit)</td><td style="text-align:right;">1 (SMP의 status word 최상위 비트)</td><td>0 = outbound, 1 = inbound</td></tr><tr><td>Hop Pointer</td><td style="text-align:right;">8</td><td>경로의 현재 위치</td></tr><tr><td>Hop Count</td><td style="text-align:right;">8</td><td>경로의 총 hop 수</td></tr><tr><td>M_Key</td><td style="text-align:right;">64</td><td>관리 보호 키</td></tr><tr><td>DrSLID</td><td style="text-align:right;">16</td><td>Directed-route source LID; <code>0xffff</code> = &quot;use path&quot;</td></tr><tr><td>DrDLID</td><td style="text-align:right;">16</td><td>Directed-route destination LID; <code>0xffff</code> = &quot;use path&quot;</td></tr></tbody></table><p>이 외에도 SMP MAD body는 포트 번호의 <code>InitialPath[64]</code>와 <code>ReturnPath[64]</code> 바이트 배열을 운반하지만, 이는 공통 SMP-DR 헤더 필드라기보다는 페이로드 필드입니다.</p><p>구체적 예시: <code>infiniband.pcap</code> frame 1은 <code>D=0, Hop Pointer=1, Hop Count=2, M_Key=0, DrSLID=0xffff, DrDLID=0xffff</code>를 가집니다 — 전형적인 second-hop 디스커버리 프로브.</p><h2 id="ipoib-encapsulation-—-4-bytes-rfc-4391" tabindex="-1">IPoIB Encapsulation — 4 bytes (RFC 4391) <a class="header-anchor" href="#ipoib-encapsulation-—-4-bytes-rfc-4391" aria-label="Permalink to &quot;IPoIB Encapsulation — 4 bytes (RFC 4391)&quot;">​</a></h2><p>IPoIB가 UD QP 위에서 IP 패킷을 운반할 때, BTH/DETH와 IP 계층 사이에 작은 헤더가 위치합니다.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Byte(s)</th><th>필드</th><th style="text-align:right;">폭</th></tr></thead><tbody><tr><td style="text-align:right;">0..1</td><td>EtherType</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">2..3</td><td>Reserved (반드시 0)</td><td style="text-align:right;">16</td></tr></tbody></table><p>보이는 EtherType 값:</p><table tabindex="0"><thead><tr><th>값</th><th>의미</th></tr></thead><tbody><tr><td><code>0x0800</code></td><td>IPv4</td></tr><tr><td><code>0x0806</code></td><td>InfiniBand ARP (RFC 4391)</td></tr><tr><td><code>0x86DD</code></td><td>IPv6</td></tr></tbody></table><p>IPoIB ARP는 EtherType에도 불구하고 Ethernet ARP와 같지 않습니다. RFC 4391은 20바이트 하드웨어 주소를 정의합니다: <code>QPN (24 bits) + Reserved (8 bits) + GID (128 bits)</code>. 그래서 <code>ib_ipping_sniffer.pcap</code>은 익숙해 보이지만 안에 IB 특유의 주소를 운반하는 ARP 레코드를 보여줍니다.</p><p>구체적 예시: <code>infiniband.pcap</code> frame 10은 <code>EtherType=0x0800, Reserved=0x0000</code>을 가지며 그 다음에 IPv4 ICMP Echo request가 옵니다. 메인 보고서의 <a href="./README_KO#erf-캡처-해부">단계별 예제</a>를 참고하세요.</p><h2 id="crc-커버리지" tabindex="-1">CRC 커버리지 <a class="header-anchor" href="#crc-커버리지" aria-label="Permalink to &quot;CRC 커버리지&quot;">​</a></h2><p>InfiniBand는 패킷 수준에서 두 CRC를 정의합니다:</p><table tabindex="0"><thead><tr><th>CRC</th><th style="text-align:right;">폭</th><th>계산 대상</th><th>목적</th></tr></thead><tbody><tr><td>ICRC (Invariant CRC)</td><td style="text-align:right;">32</td><td>가변 필드(variant header 비트)를 제외한 모든 부분</td><td>end-to-end 무결성, 스위치를 거쳐도 불변</td></tr><tr><td>VCRC (Variant CRC)</td><td style="text-align:right;">16</td><td>링크상 전체 패킷</td><td>per-link 무결성, 스위치가 재계산</td></tr></tbody></table><p>ICRC에서 제외되는 가변 필드:</p><ul><li><code>LRH.VL</code> — 스위치가 virtual lane을 remap할 수 있음</li><li><code>LRH.SL</code>/reserved 비트 — 스위치가 reserved 필드를 리셋할 수 있음</li><li><code>GRH.HopLmt</code> — 라우터가 감소시킴</li><li><code>GRH.TClass</code> — remarked 가능</li><li><code>GRH.FlowLabel</code> — remarked 가능</li><li><code>BTH.FECN</code> / <code>BECN</code> — 혼잡 통보 지점에서 설정</li><li><code>BTH</code> reserved variant 비트</li></ul><p>ERF 캡처에서는 두 CRC 모두 필터 가능한 필드(<code>infiniband.invariant.crc</code>와 <code>infiniband.variant.crc</code>)로 노출됩니다. Wireshark dissector가 직접 검증하지는 않으므로, 검증 상태를 볼 때는 <code>erf.flags.rxe</code>를 참고하세요. 메인 보고서의 <a href="./README_KO#erf가-보존하는-것-vs-숨기는-것">보존 매트릭스</a>를 참고하세요.</p><h2 id="bth-opcode-마스터-표" tabindex="-1">BTH Opcode 마스터 표 <a class="header-anchor" href="#bth-opcode-마스터-표" aria-label="Permalink to &quot;BTH Opcode 마스터 표&quot;">​</a></h2><p>8비트 OpCode는 분할됩니다: 상위 3비트가 전송 서비스, 하위 5비트가 동작을 식별합니다.</p><p>전송 서비스 prefix:</p><table tabindex="0"><thead><tr><th style="text-align:right;">비트 7..5</th><th>서비스</th><th>범위</th></tr></thead><tbody><tr><td style="text-align:right;"><code>000</code></td><td>RC (Reliable Connection)</td><td><code>0x00–0x1F</code></td></tr><tr><td style="text-align:right;"><code>001</code></td><td>UC (Unreliable Connection)</td><td><code>0x20–0x3F</code></td></tr><tr><td style="text-align:right;"><code>010</code></td><td>RD (Reliable Datagram)</td><td><code>0x40–0x5F</code></td></tr><tr><td style="text-align:right;"><code>011</code></td><td>UD (Unreliable Datagram)</td><td><code>0x60–0x7F</code></td></tr><tr><td style="text-align:right;"><code>100</code></td><td>CNP (Congestion Notification, RoCEv2 전용)</td><td><code>0x80–0x9F</code></td></tr><tr><td style="text-align:right;"><code>101</code></td><td>XRC (Extended Reliable Connection)</td><td><code>0xA0–0xBF</code></td></tr></tbody></table><p>동작 suffix (5비트, 각 전송의 범위 내에서 적용; 모든 suffix가 모든 서비스에 유효한 것은 아님):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Suffix</th><th>동작</th></tr></thead><tbody><tr><td style="text-align:right;"><code>0x00</code></td><td>SEND First</td></tr><tr><td style="text-align:right;"><code>0x01</code></td><td>SEND Middle</td></tr><tr><td style="text-align:right;"><code>0x02</code></td><td>SEND Last</td></tr><tr><td style="text-align:right;"><code>0x03</code></td><td>SEND Last with Immediate</td></tr><tr><td style="text-align:right;"><code>0x04</code></td><td>SEND Only</td></tr><tr><td style="text-align:right;"><code>0x05</code></td><td>SEND Only with Immediate</td></tr><tr><td style="text-align:right;"><code>0x06</code></td><td>RDMA WRITE First</td></tr><tr><td style="text-align:right;"><code>0x07</code></td><td>RDMA WRITE Middle</td></tr><tr><td style="text-align:right;"><code>0x08</code></td><td>RDMA WRITE Last</td></tr><tr><td style="text-align:right;"><code>0x09</code></td><td>RDMA WRITE Last with Immediate</td></tr><tr><td style="text-align:right;"><code>0x0A</code></td><td>RDMA WRITE Only</td></tr><tr><td style="text-align:right;"><code>0x0B</code></td><td>RDMA WRITE Only with Immediate</td></tr><tr><td style="text-align:right;"><code>0x0C</code></td><td>RDMA READ Request</td></tr><tr><td style="text-align:right;"><code>0x0D</code></td><td>RDMA READ Response First</td></tr><tr><td style="text-align:right;"><code>0x0E</code></td><td>RDMA READ Response Middle</td></tr><tr><td style="text-align:right;"><code>0x0F</code></td><td>RDMA READ Response Last</td></tr><tr><td style="text-align:right;"><code>0x10</code></td><td>RDMA READ Response Only</td></tr><tr><td style="text-align:right;"><code>0x11</code></td><td>Acknowledge</td></tr><tr><td style="text-align:right;"><code>0x12</code></td><td>ATOMIC Acknowledge</td></tr><tr><td style="text-align:right;"><code>0x13</code></td><td>Compare &amp; Swap</td></tr><tr><td style="text-align:right;"><code>0x14</code></td><td>Fetch &amp; Add</td></tr><tr><td style="text-align:right;"><code>0x16</code></td><td>SEND Last with Invalidate</td></tr><tr><td style="text-align:right;"><code>0x17</code></td><td>SEND Only with Invalidate</td></tr></tbody></table><p>전송 서비스별 실전 동작 지원:</p><table tabindex="0"><thead><tr><th>서비스</th><th>지원 동작</th></tr></thead><tbody><tr><td>RC</td><td>위의 모든 동작</td></tr><tr><td>UC</td><td>SEND, RDMA WRITE만 (READ 없음, Atomic 없음, ACK 없음)</td></tr><tr><td>RD</td><td>XRC 전용을 제외한 모든 동작</td></tr><tr><td>UD</td><td>SEND Only, SEND Only with Immediate (RDMA 없음, Atomic 없음, ACK 없음)</td></tr><tr><td>XRC</td><td>RC 동작에 BTH와 동작의 일반 extended header 사이에 XRCETH 추가</td></tr></tbody></table><p>이 데이터셋에서 보이는 구체적 예시:</p><table tabindex="0"><thead><tr><th style="text-align:right;">십진수</th><th>16진수</th><th>의미</th><th>위치</th></tr></thead><tbody><tr><td style="text-align:right;"><code>4</code></td><td><code>0x04</code></td><td>RC SEND Only</td><td><code>infiniband.pcap</code> frame 10</td></tr><tr><td style="text-align:right;"><code>17</code></td><td><code>0x11</code></td><td>RC Acknowledge</td><td><code>infiniband.pcap</code> frame 11</td></tr><tr><td style="text-align:right;"><code>100</code></td><td><code>0x64</code></td><td>UD SEND Only</td><td>이 데이터셋의 모든 MAD 운반 패킷</td></tr></tbody></table><h2 id="operation-→-extended-header-매핑" tabindex="-1">Operation → Extended Header 매핑 <a class="header-anchor" href="#operation-→-extended-header-매핑" aria-label="Permalink to &quot;Operation → Extended Header 매핑&quot;">​</a></h2><p>BTH 다음에 어떤 확장 헤더가 나타나는지는 opcode가 결정합니다. 헥스 덤프를 읽다가 &quot;다음에 무엇이 와야 하지?&quot;를 확인할 때 이 표를 사용하세요.</p><table tabindex="0"><thead><tr><th>동작</th><th>Extended header (BTH 다음 순서대로)</th></tr></thead><tbody><tr><td>RC/UC SEND First/Middle</td><td>(없음)</td></tr><tr><td>RC/UC SEND Last/Only</td><td>(없음)</td></tr><tr><td>RC/UC SEND Last/Only with Immediate</td><td>ImmDt</td></tr><tr><td>RC SEND Last/Only with Invalidate</td><td>IETH</td></tr><tr><td>RC/UC RDMA WRITE First</td><td>RETH</td></tr><tr><td>RC/UC RDMA WRITE Middle/Last</td><td>(없음)</td></tr><tr><td>RC/UC RDMA WRITE Last with Immediate</td><td>ImmDt</td></tr><tr><td>RC/UC RDMA WRITE Only</td><td>RETH</td></tr><tr><td>RC/UC RDMA WRITE Only with Immediate</td><td>RETH + ImmDt</td></tr><tr><td>RC RDMA READ Request</td><td>RETH</td></tr><tr><td>RC RDMA READ Response First/Last/Only</td><td>AETH</td></tr><tr><td>RC RDMA READ Response Middle</td><td>(없음)</td></tr><tr><td>RC ACK / NAK</td><td>AETH</td></tr><tr><td>RC CmpSwap / FetchAdd</td><td>AtomicETH</td></tr><tr><td>RC ATOMIC Acknowledge</td><td>AETH + AtomicAckETH</td></tr><tr><td>UD SEND Only</td><td>DETH</td></tr><tr><td>UD SEND Only with Immediate</td><td>DETH + ImmDt</td></tr><tr><td>RD 모든 동작</td><td>RDETH + DETH + (op-specific)</td></tr><tr><td>XRC 모든 동작</td><td>XRCETH + (RC 동등 extended header)</td></tr></tbody></table><p>이 데이터셋의 관리 트래픽(<code>MgmtClass</code> 태그된 MAD를 가진 UD SEND Only)의 레이아웃:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LRH → BTH → DETH → MAD common header → MAD payload → ICRC → VCRC</span></span></code></pre></div><p><code>infiniband.pcap</code> frame 10의 IPoIB ICMP를 운반하는 RC SEND Only:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LRH → BTH → IPoIB encap (4B) → IPv4 → ICMP → ICRC → VCRC</span></span></code></pre></div><p>가상의 RC RDMA READ Request → multi-packet response:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request: LRH → BTH(RDMA READ Request) → RETH → ICRC → VCRC</span></span>
<span class="line"><span>First:   LRH → BTH(RDMA READ Response First)   → AETH → payload → ICRC → VCRC</span></span>
<span class="line"><span>Middle:  LRH → BTH(RDMA READ Response Middle)  → payload         → ICRC → VCRC</span></span>
<span class="line"><span>Last:    LRH → BTH(RDMA READ Response Last)    → AETH → payload → ICRC → VCRC</span></span></code></pre></div><h2 id="참고" tabindex="-1">참고 <a class="header-anchor" href="#참고" aria-label="Permalink to &quot;참고&quot;">​</a></h2><ul><li><a href="./README_KO">메인 분석 보고서</a> — <code>ib-packets</code> 데이터셋에서 관측된 증거</li><li><a href="./README_KO#erf-캡처-해부">ERF 캡처 해부</a> — ERF 외부 레코드가 무엇을 노출하고 무엇을 숨기는지</li><li><a href="./README_KO#rdma-readwrite-패킷-분석-모델">RDMA Read/Write 패킷 분석 모델</a> — 동작 흐름과 검증 규칙</li><li>IBA Architecture Specification Volume 1, Release 1.5</li><li>Wireshark IB dissector 필드 목록: <code>tshark -G fields | grep -i infiniband</code></li><li><a href="https://cloud.tencent.com/developer/article/2513460" target="_blank" rel="noreferrer">Tencent Cloud: RDMA - IB Specification Volume 1 Transport Layer</a></li></ul>`,125)])])}const p=e(i,[["render",l]]);export{y as __pageData,p as default};
